import { type FormEvent, type ReactNode, useMemo, useState } from 'react';
import { QueryClient, QueryClientProvider, useQueryClient } from '@tanstack/react-query';
import { Link, Route, Switch, Router as WouterRouter, useLocation, useParams } from 'wouter';
import {
  Activity, AlertCircle, ArrowDown, ArrowLeft, ArrowRight, ArrowUp, ArrowUpDown, Bell, Building2, ChevronDown,
  ChevronLeft, ChevronRight, CircleHelp, ClipboardCheck, Clock3, FileCheck2, Filter,
  Landmark, LayoutDashboard, ListFilter, LogOut, Menu, MoreHorizontal, Plus, Search, Settings2,
  ShieldCheck, X, FileText, Upload, CheckCircle2, AlertTriangle,
} from 'lucide-react';
import {
  AppSettings, DemoRole, EvidenceInputEvidenceType, FdrActionInputAction, ListFdrsAttention, ListFdrsSortBy, ListFdrsSortOrder, RecordStatus,
  getGetDashboardQueryKey, getGetFdrQueryKey, getGetInstitutionQueryKey,
  getGetSettingsQueryKey, getListActivityQueryKey, getListDemoUsersQueryKey, getListFdrsQueryKey,
  getListInstitutionsQueryKey, useActOnFdr, useAddEvidence, useCreateFdr, useCreateInstitution,
  useGetDashboard, useGetFdr, useGetInstitution, useGetSession, useGetSettings, useListActivity,
  useListDemoUsers, useListFdrs, useListInstitutions, useSwitchDemoRole, useUpdateDemoUser,
  useUpdateInstitution, useUpdateSettings,
} from '@workspace/api-client-react';
import NotFound from '@/pages/not-found';

const queryClient = new QueryClient();
const roles = [
  [DemoRole.institution_user, 'Institution user'], [DemoRole.regulation_officer, 'Regulation officer'],
  [DemoRole.supervisor, 'Supervisor'], [DemoRole.administrator, 'Administrator'],
] as const;
const statusNames: Record<string, string> = {
  draft: 'Draft', submitted: 'Submitted', under_review: 'Under review', correction_required: 'Correction required',
  verified: 'Verified', rejected: 'Rejected', renewal_pending: 'Renewal pending', release_requested: 'Release requested',
  released: 'Released', closed: 'Closed',
};
const money = (value: number, currency = 'INR') => new Intl.NumberFormat('en-IN', { style: 'currency', currency, maximumFractionDigits: 0 }).format(value);
const date = (value?: string | null) => value ? new Date(value).toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' }) : '—';
const niceRole = (role?: string) => roles.find(([value]) => value === role)?.[1] ?? role?.replaceAll('_', ' ') ?? 'Reviewer';
const initials = (name = '') => name.split(/\s+/).filter(Boolean).map(s => s[0]).slice(0, 2).join('').toUpperCase() || 'FS';

function App() {
  return <QueryClientProvider client={queryClient}>
    <WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><ShellRoutes /></WouterRouter>
  </QueryClientProvider>;
}

function ShellRoutes() {
  const [path] = useLocation();
  const session = useGetSession();
  const switchRole = useSwitchDemoRole();
  const qc = useQueryClient();
  const [mobileMenu, setMobileMenu] = useState(false);
  const [headerPanel, setHeaderPanel] = useState<'notifications' | 'profile' | null>(null);
  const isAdmin = session.data?.role === DemoRole.administrator;
  if (session.isLoading) return <div className="min-h-[100dvh] bg-[#f3f6f8] p-8"><div className="mx-auto max-w-6xl animate-pulse"><div className="h-8 w-56 rounded bg-slate-200"/><div className="mt-8 h-36 rounded-xl bg-white"/><div className="mt-5 grid gap-4 md:grid-cols-3"><div className="h-40 rounded-xl bg-white"/><div className="h-40 rounded-xl bg-white"/><div className="h-40 rounded-xl bg-white"/></div></div></div>;
  if (session.isError || !session.data) return <div className="grid min-h-[100dvh] place-items-center p-6"><div className="max-w-md rounded-2xl border bg-white p-8 text-center shadow-sm"><AlertCircle className="mx-auto h-9 w-9 text-amber-600"/><h1 className="display mt-4 text-2xl font-bold">The assurance workspace is unavailable</h1><p className="mt-2 text-sm text-slate-600">We could not establish a demo session. Check the service and try again.</p><button className="mt-5 rounded-lg bg-[#183452] px-5 py-2.5 text-sm font-semibold text-white" onClick={() => session.refetch()} data-testid="button-retry-session">Retry connection</button></div></div>;
  const s = session.data;
  const nav = [
    { href: '/dashboard', title: 'Overview', icon: LayoutDashboard },
    { href: '/records', title: 'FDR repository', icon: FileCheck2 },
    { href: '/institutions', title: 'Institutions', icon: Building2 },
    { href: '/activity', title: 'Audit activity', icon: Activity },
  ];
  const current = (path === '/' ? '/dashboard' : path).startsWith('/records') ? 'FDR repository'
    : path.startsWith('/institutions') ? 'Institutions' : path.startsWith('/activity') ? 'Audit activity'
      : path.startsWith('/admin') ? 'Administration' : 'Overview';
  const goRole = (role: (typeof roles)[number][0]) => switchRole.mutate({ data: { role } }, { onSuccess: () => qc.invalidateQueries() });
  return <div className="min-h-[100dvh] bg-[#f4f6f8] text-[#172a40]">
    <aside className={`fixed inset-y-0 left-0 z-40 flex w-[254px] flex-col bg-[#122943] text-white transition-transform duration-300 lg:translate-x-0 ${mobileMenu ? 'translate-x-0' : '-translate-x-full'}`}>
      <div className="relative flex min-h-[98px] items-center gap-3 border-b border-white/10 px-5 py-3">
        <div aria-hidden="true" className="grid h-11 w-11 shrink-0 place-items-center rounded-xl border border-[#e3ad42]/45 bg-[#e3ad42] font-black tracking-[-.12em] text-[#122943] shadow-[inset_0_0_0_3px_rgba(18,41,67,.12)]">EV</div>
        <div className="min-w-0">
          <div className="display text-[17px] font-extrabold leading-tight tracking-tight">EduVeriX</div>
          <div className="mt-1 text-[11px] font-bold leading-tight text-[#f1c66c]">FDR Sentinel</div>
          <div className="mt-1 max-w-[158px] text-[8px] font-semibold leading-[1.35] tracking-[.035em] text-slate-400">Innovation Team | Smart India Hackathon 2026</div>
        </div>
        <button className="ml-auto rounded-md p-1 text-slate-300 lg:hidden" onClick={() => setMobileMenu(false)} aria-label="Close navigation" data-testid="button-close-menu"><X size={19}/></button>
      </div>
      <div className="px-5 pt-7 pb-2 text-[10px] font-bold uppercase tracking-[.16em] text-slate-500">Institutional assurance</div>
      <nav className="space-y-1 px-3">
        {nav.map(item => <Link key={item.href} href={item.href} onClick={() => setMobileMenu(false)} data-testid={`link-nav-${item.href.slice(1)}`} className={`group flex items-center gap-3 rounded-lg px-3 py-2.5 text-[13px] font-medium transition-colors ${current === item.title ? 'bg-white/10 text-white' : 'text-slate-300 hover:bg-white/5 hover:text-white'}`}>
          <item.icon size={17} strokeWidth={current === item.title ? 2.2 : 1.8}/><span>{item.title}</span>{current === item.title && <span className="ml-auto h-1.5 w-1.5 rounded-full bg-[#e3ad42]"/>}
        </Link>)}
      </nav>
      {isAdmin && <><div className="px-5 pt-8 pb-2 text-[10px] font-bold uppercase tracking-[.16em] text-slate-500">System</div><nav className="px-3"><Link href="/admin" data-testid="link-nav-admin" className={`flex items-center gap-3 rounded-lg px-3 py-2.5 text-[13px] font-medium ${current === 'Administration' ? 'bg-white/10 text-white' : 'text-slate-300 hover:bg-white/5'}`}><Settings2 size={17}/>Administration</Link></nav></>}
      <div className="mt-auto p-4">
        <div className="rounded-xl border border-white/10 bg-white/[.045] p-3.5">
          <div className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-wider text-slate-400"><span className="h-1.5 w-1.5 rounded-full bg-emerald-400"/>Prototype environment</div>
          <p className="mt-2 text-[11px] leading-relaxed text-slate-300">Demonstration data only. No official submissions are processed here.</p>
        </div>
        <div className="mt-4 flex items-center gap-2 border-t border-white/10 pt-4 text-[10px] text-slate-500"><CircleHelp size={14}/>Help &amp; guidance <span className="ml-auto">v0.8.4</span></div>
      </div>
    </aside>
    {mobileMenu && <button aria-label="Close navigation overlay" className="fixed inset-0 z-30 bg-slate-950/35 lg:hidden" onClick={() => setMobileMenu(false)} data-testid="button-nav-overlay"/>}
    <div className="min-h-[100dvh] lg:pl-[254px]">
      <header className="sticky top-0 z-20 flex h-[69px] items-center justify-between border-b border-[#dce3e9] bg-white/95 px-4 backdrop-blur md:px-8">
        <div className="flex items-center gap-3"><button onClick={() => setMobileMenu(true)} className="rounded-lg p-2 text-slate-600 hover:bg-slate-100 lg:hidden" aria-label="Open navigation" data-testid="button-open-menu"><Menu size={20}/></button><div className="text-sm font-semibold text-[#253d55]">{current}</div><span className="hidden h-4 border-l border-slate-200 sm:block"/><span className="hidden text-xs text-slate-500 sm:block">EduVeriX · Security Deposit / FDR Portal</span></div>
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-1.5 rounded-md border border-[#e2e7eb] bg-[#f8fafb] px-2 py-1.5 sm:gap-2 sm:px-2.5"><span className="hidden text-[9px] font-bold uppercase tracking-wider text-slate-500 md:block">Demo role</span><select aria-label="Switch demo role" className="max-w-[105px] cursor-pointer border-0 bg-transparent text-[10px] font-semibold outline-none sm:max-w-[135px] sm:text-xs" value={s.role} onChange={e => goRole(e.target.value as (typeof roles)[number][0])} data-testid="select-demo-role">{roles.map(([value,label]) => <option value={value} key={value}>{label}</option>)}</select><ChevronDown size={13} className="text-slate-400"/></div>
          <div className="relative"><button onClick={()=>setHeaderPanel(headerPanel==='notifications'?null:'notifications')} className="relative rounded-lg p-2 text-slate-500 hover:bg-slate-100" aria-label="Notifications" aria-expanded={headerPanel==='notifications'} data-testid="button-notifications"><Bell size={18}/><span className="absolute right-1.5 top-1.5 h-1.5 w-1.5 rounded-full bg-[#dca837] ring-2 ring-white"/></button>{headerPanel==='notifications'&&<div className="absolute right-0 top-12 z-30 w-[280px] rounded-xl border border-slate-200 bg-white p-4 shadow-xl" data-testid="panel-notifications"><div className="text-xs font-bold text-[#213b55]">Workspace notices</div><p className="mt-2 text-[11px] leading-relaxed text-slate-600">Prototype environment is active. Notifications reflect demonstration data only.</p><button onClick={()=>setHeaderPanel(null)} className="mt-3 text-[10px] font-bold text-[#315b7d]" data-testid="button-dismiss-notifications">Dismiss</button></div>}</div>
          <div className="relative flex items-center gap-2.5 border-l border-slate-200 pl-3"><div className="grid h-8 w-8 place-items-center rounded-full bg-[#e9eef3] text-[11px] font-bold text-[#24435f]" data-testid="avatar-current-user" aria-label={`${niceRole(s.role)} demo role`}>{initials(niceRole(s.role))}</div><div className="hidden leading-tight sm:block"><div className="max-w-[150px] truncate text-xs font-semibold" data-testid="text-current-user">{niceRole(s.role)}</div><div className="mt-0.5 text-[10px] text-slate-500">EduVeriX demo</div></div><button onClick={()=>setHeaderPanel(headerPanel==='profile'?null:'profile')} className="rounded p-1 text-slate-400 hover:bg-slate-100 hover:text-slate-700" aria-label="Profile options" aria-expanded={headerPanel==='profile'} data-testid="button-profile-menu"><MoreHorizontal size={18}/></button>{headerPanel==='profile'&&<div className="absolute right-0 top-12 z-30 w-[240px] rounded-xl border border-slate-200 bg-white p-4 shadow-xl" data-testid="panel-profile"><div className="text-xs font-bold text-[#213b55]">EduVeriX demo role</div><div className="mt-1 text-[10px] text-slate-500">Active workspace role</div><div className="mt-3 border-t pt-3 text-[10px] text-slate-600">{niceRole(s.role)}{s.demoMode?' · Demo session':''}</div>{isAdmin&&<Link href="/admin" onClick={()=>setHeaderPanel(null)} className="mt-3 block rounded-md bg-slate-50 px-3 py-2 text-[10px] font-bold text-[#315b7d]" data-testid="link-profile-admin">Administration settings</Link>}</div>}</div>
        </div>
      </header>
      <div className="border-b border-[#ead6aa] bg-[#fff7e7] px-4 py-2 text-center text-[10px] font-bold tracking-[.035em] text-[#77571f] sm:text-[11px]" data-testid="banner-prototype">Hackathon Prototype — Not an Official AICTE Service</div>
      <main className="mx-auto max-w-[1510px] p-4 pb-12 md:px-8 md:pt-7 lg:px-10">
        <Switch>
          <Route path="/" component={DashboardPage}/><Route path="/dashboard" component={DashboardPage}/>
          <Route path="/records" component={RecordsPage}/><Route path="/records/:id" component={RecordPage}/>
          <Route path="/institutions" component={InstitutionsPage}/><Route path="/institutions/:id" component={InstitutionPage}/>
          <Route path="/admin" component={AdminPage}/><Route path="/activity" component={ActivityPage}/>
          <Route component={NotFound}/>
        </Switch>
      </main>
      <footer className="border-t border-[#e1e6ea] px-5 py-4 text-center text-[10px] text-slate-500 md:text-left md:px-10"><span className="font-semibold text-slate-600">EduVeriX</span><span className="mx-2">/</span><span className="font-semibold text-slate-600">FDR Sentinel</span><span className="mx-2">/</span>Institutional assurance demonstration<span className="float-right hidden md:inline">Prototype environment · Data shown is illustrative</span></footer>
    </div>
  </div>;
}

function Title({ eyebrow, title, subtitle, action }: { eyebrow?: string; title: string; subtitle?: string; action?: ReactNode }) {
  return <div className="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div>{eyebrow && <div className="mb-1.5 text-[10px] font-bold uppercase tracking-[.16em] text-[#a67a28]">{eyebrow}</div>}<h1 className="display text-[27px] font-extrabold tracking-[-.035em] text-[#172d46] md:text-[32px]" data-testid="heading-page">{title}</h1>{subtitle && <p className="mt-1.5 max-w-2xl text-[13px] leading-relaxed text-slate-600">{subtitle}</p>}</div>{action}</div>;
}
function Panel({ children, className = '', title, right }: { children: ReactNode; className?: string; title?: string; right?: ReactNode }) {
  return <section className={`rounded-xl border border-[#dfe5e9] bg-white shadow-[0_2px_8px_rgba(18,41,67,.025)] ${className}`}>{(title || right) && <div className="flex min-h-[54px] items-center justify-between border-b border-[#edf0f2] px-5"><h2 className="text-[13px] font-bold text-[#263e55]">{title}</h2>{right}</div>}{children}</section>;
}
function StateBox({ error, retry, empty = false }: { error?: boolean; retry?: () => void; empty?: boolean }) {
  return <div className="flex min-h-[180px] flex-col items-center justify-center px-6 text-center" data-testid={error ? 'state-error' : 'state-empty'}>{error ? <AlertCircle className="h-7 w-7 text-amber-600"/> : <FileText className="h-7 w-7 text-slate-300"/>}<div className="mt-3 text-sm font-semibold text-slate-700">{error ? 'We could not load this information' : empty ? 'No matching records' : 'Nothing to display yet'}</div><p className="mt-1 max-w-sm text-xs text-slate-500">{error ? 'Your work is safe. Check your connection and retry.' : 'When information is available, it will appear here.'}</p>{error && retry && <button onClick={retry} className="mt-3 rounded-md border px-3 py-1.5 text-xs font-semibold hover:bg-slate-50" data-testid="button-retry">Try again</button>}</div>;
}
function Badge({ children, tone = 'slate' }: { children: ReactNode; tone?: string }) {
  const tones: Record<string,string> = { slate:'bg-slate-100 text-slate-700',green:'bg-emerald-50 text-emerald-800',amber:'bg-amber-50 text-amber-800',red:'bg-rose-50 text-rose-800',blue:'bg-sky-50 text-sky-800' };
  return <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-[10px] font-bold ${tones[tone] ?? tones.slate}`}>{children}</span>;
}
const statusTone = (status: string) => ['verified','released','closed'].includes(status) ? 'green' : ['rejected'].includes(status) ? 'red' : ['correction_required','renewal_pending','release_requested'].includes(status) ? 'amber' : 'blue';
const riskTone = (risk: string) => risk === 'high' ? 'red' : risk === 'medium' ? 'amber' : 'green';
function Button({ children, onClick, kind = 'primary', testId, disabled, type = 'button' }: { children: ReactNode; onClick?: () => void; kind?: 'primary'|'secondary'|'quiet'; testId: string; disabled?: boolean; type?: 'button'|'submit' }) {
  const cls = kind === 'primary' ? 'bg-[#183653] text-white hover:bg-[#244a70]' : kind === 'secondary' ? 'border border-[#cbd6de] bg-white text-[#29445e] hover:bg-[#f5f8fa]' : 'text-[#52687b] hover:bg-slate-100';
  return <button type={type} onClick={onClick} disabled={disabled} className={`inline-flex items-center justify-center gap-2 rounded-lg px-3.5 py-2 text-xs font-bold transition-colors disabled:cursor-not-allowed disabled:opacity-50 ${cls}`} data-testid={testId}>{children}</button>;
}

function DashboardPage() {
  const { data, isLoading, isError, refetch } = useGetDashboard();
  useGetSession();
  const records = useListFdrs({ page: 1, pageSize: 5 });
  if (isLoading) return <DashboardSkeleton/>;
  if (isError || !data) return <><Title eyebrow="Problem Statement 26265" title="EduVeriX" subtitle="Innovation Team | Smart India Hackathon 2026 · FDR Sentinel — Intelligent Security Deposit Assurance."/><Panel><StateBox error retry={() => refetch()}/></Panel></>;
  const metrics = data.metrics ?? [];
  const pending = metrics.find(m => /pending|review/i.test(m.key + ' ' + m.label))?.value ?? data.statusBreakdown.filter(x => ['submitted','under_review'].includes(x.status)).reduce((a,b)=>a+b.count,0);
  return <div className="page-enter">
    <Title eyebrow="Problem Statement 26265" title="EduVeriX" subtitle="Innovation Team | Smart India Hackathon 2026" action={<div className="flex items-center gap-2 text-[11px] text-slate-500"><span className="h-2 w-2 rounded-full bg-emerald-500"/>Data refreshed just now</div>}/>
    <div className="mb-5 flex flex-col gap-3 rounded-xl bg-[#183653] p-5 text-white shadow-sm sm:flex-row sm:items-center sm:justify-between md:px-7">
      <div className="flex gap-4"><div className="hidden h-12 w-12 shrink-0 place-items-center rounded-xl border border-[#e9b54b]/40 bg-white/10 font-black tracking-[-.12em] text-[#e9b54b] sm:grid" aria-hidden="true">EV</div><div><div className="flex flex-wrap items-center gap-x-2 gap-y-1 text-[10px] font-bold uppercase tracking-[.16em] text-[#e9b54b]"><span>Security Deposit / FDR Portal</span><span className="h-1 w-1 rounded-full bg-white/40"/><span>Prototype view</span></div><div className="display mt-1 text-xl font-bold tracking-tight">FDR Sentinel</div><p className="mt-1 text-xs font-semibold text-slate-200">Intelligent Security Deposit Assurance</p><p className="mt-1 text-xs text-slate-300">Monitor institutional deposits, upcoming maturities and review obligations in one place.</p></div></div>
      <Link href="/records" className="inline-flex shrink-0 items-center justify-center gap-2 rounded-lg bg-[#e8b448] px-4 py-2.5 text-xs font-bold text-[#1b344e] hover:bg-[#f0c46c]" data-testid="link-view-records">Open FDR repository <ArrowRight size={15}/></Link>
    </div>
    <div className="grid grid-cols-2 gap-3 md:grid-cols-3 xl:grid-cols-4">
      {(metrics.length ? metrics : [
        {key:'total_fdrs',label:'FDR records',value:records.data?.total ?? 0,filter:null},
        {key:'pending_review',label:'Awaiting review',value:pending,filter:'under_review'},
        {key:'maturing_30_days',label:'Maturing in 30 days',value:0,filter:null},
        {key:'open_issues',label:'Open issues',value:0,filter:null},
      ]).map((m,i) => {
        const icons = [FileCheck2, ClipboardCheck, Clock3, AlertTriangle]; const Icon = icons[i] ?? FileText;
        const filter = (m.filter ?? '').toLowerCase();
        const href = filter === 'institutions' ? '/institutions'
          : filter === 'all' ? '/records'
            : ['verified','renewal_pending','release_requested'].includes(filter) ? `/records?status=${filter}`
              : ['pending','maturing','overdue','urgent'].includes(filter) ? `/records?attention=${filter}`
                : '/records';
        return <Link href={href} key={m.key} className="group rounded-xl border border-[#dfe5e9] bg-white p-4 shadow-[0_2px_8px_rgba(18,41,67,.025)] transition hover:-translate-y-0.5 hover:border-[#b6c5d0] hover:shadow-sm md:p-5" data-testid={`metric-card-${m.key}`}><div className="flex items-center justify-between"><span className="text-[11px] font-semibold leading-snug text-slate-500">{m.label}</span><span className={`grid h-8 w-8 place-items-center rounded-lg ${i===2?'bg-amber-50 text-amber-700':'bg-[#edf2f6] text-[#31516d]'}`}><Icon size={16}/></span></div><div className="display mt-3 text-[27px] font-extrabold tracking-tight text-[#183653]">{Number(m.value).toLocaleString('en-IN')}</div><div className="mt-1 flex items-center justify-between text-[10px] text-slate-400"><span>{i === 2 ? 'Requires forward planning' : i === 1 ? 'Across active queue' : 'Across participating institutions'}</span><ArrowRight size={13} className="text-slate-300 transition group-hover:translate-x-0.5 group-hover:text-[#315b7d]"/></div></Link>;
      })}
    </div>
    <div className="mt-5">
      <Panel title="FDR status distribution" right={<span className="text-[10px] text-slate-500">Current repository mix</span>}>
        {data.statusBreakdown?.length ? <div className="grid gap-x-8 gap-y-4 p-5 sm:grid-cols-2" data-testid="chart-status-breakdown">{data.statusBreakdown.map(item=>{const total=Math.max(1,data.statusBreakdown.reduce((sum,x)=>sum+x.count,0));return <Link key={item.status} href={`/records?status=${item.status}`} className="group" data-testid={`status-breakdown-${item.status}`}><div className="mb-1.5 flex items-center justify-between gap-3"><span className="text-[11px] font-semibold text-slate-700 group-hover:text-[#315b7d]">{statusNames[item.status]??item.status}</span><span className="mono text-[10px] text-slate-500">{item.count}</span></div><div className="h-2 overflow-hidden rounded-full bg-[#edf1f4]"><div className={`h-full rounded-full ${['verified','released','closed'].includes(item.status)?'bg-[#56836b]':['rejected'].includes(item.status)?'bg-[#be6d65]':['correction_required','renewal_pending','release_requested'].includes(item.status)?'bg-[#d5a13b]':'bg-[#315b7d]'}`} style={{width:`${Math.max(item.count?2:0,item.count/total*100)}%`}}/></div></Link>})}</div> : <StateBox empty/>}
      </Panel>
    </div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1.5fr_1fr]">
      <Panel title="Maturity watch" right={<span className="text-[10px] font-medium text-slate-500">Deposit maturity by month</span>}>
        {data.maturityTrend?.length ? <div className="px-5 pt-5 pb-4"><div className="flex h-[180px] items-end gap-2 border-b border-l border-slate-200 px-3">{data.maturityTrend.map((point,i)=>{const max=Math.max(1,...data.maturityTrend.map(p=>p.upcoming+p.matured));const h=Math.max(8,((point.upcoming+point.matured)/max)*142);return <div key={point.month+i} className="group flex flex-1 flex-col items-center justify-end gap-1"><div className="w-full max-w-[44px] overflow-hidden rounded-t-sm bg-[#dfeaf0]" style={{height:`${h}px`}}><div className="w-full bg-[#244f70]" style={{height:`${point.upcoming/(point.upcoming+point.matured||1)*100}%`}}/></div><span className="mb-[-20px] mt-1 text-[9px] text-slate-500">{point.month}</span></div>})}</div><div className="mt-7 flex gap-5 text-[10px] text-slate-500"><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-sm bg-[#244f70]"/>Upcoming</span><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-sm bg-[#dfeaf0]"/>Matured</span></div></div> : <StateBox empty/>}
      </Panel>
      <Panel title="Review queue" right={<Link href="/records" className="text-[10px] font-bold text-[#325b7c]" data-testid="link-review-queue">View repository <ArrowRight className="ml-1 inline" size={12}/></Link>}>
        {records.isLoading ? <div className="space-y-3 p-5">{[1,2,3].map(i=><div key={i} className="h-12 animate-pulse rounded bg-slate-100"/> )}</div> : records.isError ? <StateBox error retry={()=>records.refetch()}/> : records.data?.items?.length ? <div>{records.data.items.slice(0,5).map(r=><Link href={`/records/${r.id}`} key={r.id} className="flex items-center gap-3 border-b border-[#eef1f3] px-5 py-3.5 last:border-0 hover:bg-slate-50" data-testid={`row-dashboard-record-${r.id}`}><div className="grid h-9 w-9 shrink-0 place-items-center rounded-lg bg-[#edf2f6] text-[#3d5b74]"><FileText size={16}/></div><div className="min-w-0 flex-1"><div className="truncate text-xs font-bold text-[#263d53]">{r.institutionName}</div><div className="mono mt-1 text-[10px] text-slate-500">{r.referenceNumber} · {r.bankName}</div></div><div className="hidden text-right sm:block"><Badge tone={statusTone(r.status)}>{statusNames[r.status] ?? r.status}</Badge><div className="mt-1 text-[10px] text-slate-500">Matures {date(r.maturityDate)}</div></div><ChevronRight size={15} className="text-slate-400"/></Link>)}</div> : <StateBox empty/>}
      </Panel>
    </div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1fr_1fr]">
      <Panel title="Regional submissions" right={<span className="text-[10px] text-slate-500">FDR records by region</span>}>
        {data.institutionSubmissions?.length ? <div className="space-y-3 p-5">{data.institutionSubmissions.map((r,i)=>{const max=Math.max(...data.institutionSubmissions.map(x=>x.count),1);return <div key={r.region} data-testid={`region-summary-${i}`}><div className="mb-1.5 flex justify-between text-[11px]"><span className="font-semibold text-slate-700">{r.region}</span><span className="mono text-slate-500">{r.count}</span></div><div className="h-1.5 rounded bg-[#eef1f3]"><div className="h-full rounded bg-[#315b7d]" style={{width:`${Math.max(4,r.count/max*100)}%`}}/></div></div>})}</div> : <StateBox empty/>}
      </Panel>
      <Panel title="Officer workload" right={<span className="text-[10px] text-slate-500">Assigned queue</span>}>
        {data.caseWorkload?.length ? <div className="divide-y divide-[#eef1f3]">{data.caseWorkload.slice(0,5).map((o,i)=><div key={o.officer+i} className="flex items-center gap-3 px-5 py-3" data-testid={`workload-officer-${i}`}><div className="grid h-8 w-8 place-items-center rounded-full bg-[#eaf0f4] text-[10px] font-bold text-[#36536e]">{initials(o.officer)}</div><div className="flex-1 text-xs font-semibold text-slate-700">{o.officer}</div><div className="text-right"><div className="mono text-xs font-bold text-[#27435e]">{o.pending} pending</div><div className={`mt-0.5 text-[10px] ${o.overdue?'text-rose-700':'text-slate-500'}`}>{o.overdue} overdue</div></div></div>)}</div> : <StateBox empty/>}
      </Panel>
    </div>
    <div className="mt-5"><ActivityPanel events={data.recentActivity ?? []} compact/></div>
    <div className="mt-5 rounded-lg border border-[#e3e8ec] bg-[#f8fafb] px-4 py-3 text-[10px] leading-relaxed text-slate-500"><span className="font-bold text-slate-600">Prototype disclosure</span> · This demonstration supports workflow exploration only. It is not an official service and does not create, verify or release any institutional deposit.</div>
  </div>;
}
function DashboardSkeleton(){return <div className="animate-pulse"><div className="mb-7 h-20 w-1/2 rounded bg-slate-200"/><div className="h-28 rounded-xl bg-slate-200"/><div className="mt-5 grid grid-cols-2 gap-3 lg:grid-cols-4">{[1,2,3,4].map(x=><div key={x} className="h-32 rounded-xl bg-slate-200"/> )}</div><div className="mt-5 grid gap-5 md:grid-cols-2"><div className="h-64 rounded-xl bg-slate-200"/><div className="h-64 rounded-xl bg-slate-200"/></div></div>}

function RecordsPage() {
  const [search,setSearch]=useState(()=>new URLSearchParams(window.location.search).get('q')??'');
  const [status,setStatus]=useState(()=>new URLSearchParams(window.location.search).get('status')??'');
  const [attention,setAttention]=useState(()=>new URLSearchParams(window.location.search).get('attention')??'');
  const [page,setPage]=useState(1);const [showForm,setShowForm]=useState(false);
  const [sortBy,setSortBy]=useState<typeof ListFdrsSortBy[keyof typeof ListFdrsSortBy]|undefined>();
  const [sortOrder,setSortOrder]=useState<typeof ListFdrsSortOrder[keyof typeof ListFdrsSortOrder]>('asc');
  const params={q:search||undefined,status:(status||undefined) as typeof RecordStatus[keyof typeof RecordStatus]|undefined,attention:(attention||undefined) as typeof ListFdrsAttention[keyof typeof ListFdrsAttention]|undefined,sortBy,sortOrder:sortBy?sortOrder:undefined,page,pageSize:10};
  const q=useListFdrs(params); const inst=useListInstitutions({page:1,pageSize:100});
  const create=useCreateFdr();const qc=useQueryClient();
  const submit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const d=new FormData(e.currentTarget);create.mutate({data:{institutionId:String(d.get('institutionId')),bankName:String(d.get('bankName')),branchName:String(d.get('branchName')),referenceNumber:String(d.get('referenceNumber')),amount:Number(d.get('amount')),currency:'INR',issueDate:String(d.get('issueDate')),maturityDate:String(d.get('maturityDate'))}}, {onSuccess:()=>{setShowForm(false);qc.invalidateQueries({queryKey:getListFdrsQueryKey()});qc.invalidateQueries({queryKey:getGetDashboardQueryKey()})}})};
  const maxPage=Math.max(1,Math.ceil((q.data?.total??0)/(q.data?.pageSize??10)));
  const changeSort=(field:typeof ListFdrsSortBy[keyof typeof ListFdrsSortBy])=>{if(sortBy===field)setSortOrder(order=>order==='asc'?'desc':'asc');else{setSortBy(field);setSortOrder('asc')}setPage(1)};
  const sortHeader=(label:string,field:typeof ListFdrsSortBy[keyof typeof ListFdrsSortBy])=>{const active=sortBy===field;const direction=active?sortOrder==='asc'?'ascending':'descending':'not sorted';const Icon=active?(sortOrder==='asc'?ArrowUp:ArrowDown):ArrowUpDown;return <button type="button" onClick={()=>changeSort(field)} aria-label={`Sort by ${label}, ${direction}`} className="inline-flex items-center gap-1.5 whitespace-nowrap text-left font-bold uppercase tracking-[.12em] text-slate-500 hover:text-[#244b6d] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#b4842e]" data-testid={`button-sort-${field}`}>{label}<Icon size={12} aria-hidden="true"/></button>};
  return <div className="page-enter"><Title eyebrow="Deposit register" title="FDR repository" subtitle="Find, triage and follow fixed deposit records across participating institutions." action={<Button onClick={()=>setShowForm(true)} testId="button-new-fdr"><Plus size={15}/>Submit FDR</Button>}/>
    <Panel className="overflow-hidden"><div className="flex flex-col gap-3 border-b border-[#edf0f2] p-4 md:flex-row md:items-center md:justify-between"><label className="relative min-w-0 flex-1 md:max-w-[420px]"><Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/><input value={search} onChange={e=>{setSearch(e.target.value);setPage(1)}} placeholder="Search institution, bank or reference" className="h-10 w-full rounded-lg border border-[#dce3e9] bg-[#fbfcfd] pl-9 pr-3 text-xs outline-none focus:border-[#547590]" data-testid="input-search-fdr"/></label><div className="flex flex-wrap items-center gap-2"><ListFilter size={15} className="text-slate-500"/><select value={status} onChange={e=>{setStatus(e.target.value);setPage(1)}} className="h-10 flex-1 rounded-lg border border-[#dce3e9] bg-white px-3 text-xs text-slate-700 md:flex-none" aria-label="Filter by FDR status" data-testid="select-filter-status"><option value="">All statuses</option>{Object.entries(statusNames).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select><select value={attention} onChange={e=>{setAttention(e.target.value);setPage(1)}} className="h-10 flex-1 rounded-lg border border-[#dce3e9] bg-white px-3 text-xs text-slate-700 md:flex-none" aria-label="Filter by attention" data-testid="select-filter-attention"><option value="">All attention</option>{Object.entries({pending:'Pending',maturing:'Maturing',overdue:'Overdue',urgent:'Urgent'}).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select><Button kind="secondary" testId="button-filters" onClick={()=>{setSearch('');setStatus('');setAttention('');setPage(1)}}><Filter size={14}/>Clear</Button></div></div>
      <div className="scrollbar-thin overflow-x-auto"><table className="w-full min-w-[980px] border-collapse text-left"><thead><tr className="bg-[#f8fafb] text-[9px]"><th className="px-5 py-3">{sortHeader('Institution','institutionName')}</th><th className="px-4 py-3">{sortHeader('Reference','referenceNumber')}</th><th className="px-4 py-3">{sortHeader('Bank','bankName')}</th><th className="px-4 py-3">{sortHeader('Principal','amount')}</th><th className="px-4 py-3">{sortHeader('Maturity','maturityDate')}</th><th className="px-4 py-3">{sortHeader('Status','status')}</th><th className="px-4 py-3">{sortHeader('Risk','riskLevel')}</th><th className="px-4 py-3"/></tr></thead>
        <tbody className="divide-y divide-[#edf0f2]">{q.isLoading ? [1,2,3,4,5].map(i=><tr key={i}><td colSpan={8} className="p-4"><div className="h-9 animate-pulse rounded bg-slate-100"/></td></tr>) : q.isError ? <tr><td colSpan={8}><StateBox error retry={()=>q.refetch()}/></td></tr> : !q.data?.items?.length ? <tr><td colSpan={8}><StateBox empty/></td></tr> : q.data.items.map(r=><tr key={r.id} className="group hover:bg-[#fafcfd]" data-testid={`row-fdr-${r.id}`}><td className="px-5 py-3.5"><Link href={`/records/${r.id}`} className="block"><div className="text-xs font-bold text-[#25435e] group-hover:underline">{r.institutionName}</div><div className="mono mt-1 text-[10px] text-slate-500">{r.institutionIdentifier}</div></Link></td><td className="px-4 py-3.5"><Link href={`/records/${r.id}`} className="mono text-[10px] text-[#315b7d]" data-testid={`link-reference-${r.id}`}>{r.referenceNumber}</Link></td><td className="px-4 py-3.5"><div className="text-xs font-semibold text-slate-700">{r.bankName}</div><div className="mt-1 text-[10px] text-slate-500">{r.branchName}</div></td><td className="px-4 py-3.5 mono text-xs font-semibold">{money(r.amount,r.currency)}</td><td className="px-4 py-3.5 text-xs">{date(r.maturityDate)}</td><td className="px-4 py-3.5"><Badge tone={statusTone(r.status)}>{statusNames[r.status] ?? r.status}</Badge></td><td className="px-4 py-3.5"><Badge tone={riskTone(r.riskLevel)}>{r.riskLevel}</Badge></td><td className="px-4 py-3.5"><Link href={`/records/${r.id}`} className="rounded p-1.5 text-slate-400 hover:bg-slate-100 hover:text-slate-700" aria-label={`Open ${r.referenceNumber}`} data-testid={`link-open-fdr-${r.id}`}><ArrowRight size={15}/></Link></td></tr>)}</tbody></table></div>
      <div className="flex flex-col gap-2 border-t border-[#edf0f2] px-4 py-3 sm:flex-row sm:items-center sm:justify-between"><span className="text-[10px] text-slate-500" data-testid="text-record-count">{q.data?.total ?? 0} records · Page {page} of {maxPage}</span><div className="flex gap-2"><Button kind="secondary" disabled={page<=1} onClick={()=>setPage(p=>Math.max(1,p-1))} testId="button-page-previous"><ChevronLeft size={14}/>Previous</Button><Button kind="secondary" disabled={page>=maxPage} onClick={()=>setPage(p=>Math.min(maxPage,p+1))} testId="button-page-next">Next<ChevronRight size={14}/></Button></div></div>
    </Panel>
    {showForm && <Modal title="Submit a fixed deposit record" close={()=>setShowForm(false)}><form onSubmit={submit} className="space-y-3"><div className="grid gap-3 sm:grid-cols-2"><label className="field sm:col-span-2">Institution<select required name="institutionId" className="input" data-testid="select-fdr-institution"><option value="">Select institution</option>{inst.data?.items?.map(i=><option key={i.id} value={i.id}>{i.name}</option>)}</select></label><label className="field">Bank name<input name="bankName" required className="input" data-testid="input-bank-name"/></label><label className="field">Branch name<input name="branchName" required className="input" data-testid="input-branch-name"/></label><label className="field">FDR reference<input name="referenceNumber" required className="input" data-testid="input-reference"/></label><label className="field">Principal amount (INR)<input name="amount" required type="number" min="1" className="input" data-testid="input-amount"/></label><label className="field">Issue date<input name="issueDate" required type="date" className="input" data-testid="input-issue-date"/></label><label className="field">Maturity date<input name="maturityDate" required type="date" className="input" data-testid="input-maturity-date"/></label></div>{create.isError&&<p className="text-xs text-rose-700">Submission failed. Review the details and retry.</p>}<div className="flex justify-end gap-2 pt-2"><Button kind="secondary" onClick={()=>setShowForm(false)} testId="button-cancel-fdr">Cancel</Button><Button type="submit" disabled={create.isPending} testId="button-submit-fdr">{create.isPending?'Submitting…':'Submit record'}</Button></div></form></Modal>}
  </div>;
}

function Modal({title,close,children}:{title:string;close:()=>void;children:ReactNode}){return <div className="fixed inset-0 z-50 grid place-items-center bg-[#11243a]/45 p-4" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><div role="dialog" aria-modal="true" aria-label={title} className="page-enter max-h-[90vh] w-full max-w-[560px] overflow-y-auto rounded-2xl bg-white p-5 shadow-2xl sm:p-7"><div className="mb-5 flex items-start justify-between"><h2 className="display pr-4 text-xl font-extrabold text-[#1d3650]">{title}</h2><button onClick={close} className="rounded p-1 text-slate-500 hover:bg-slate-100" aria-label="Close dialog" data-testid="button-close-modal"><X size={19}/></button></div>{children}</div></div>}

function RecordPage(){
  const {id=''}=useParams<{id:string}>();const q=useGetFdr(id,{query:{enabled:!!id,queryKey:getGetFdrQueryKey(id)}});const act=useActOnFdr();const add=useAddEvidence();const qc=useQueryClient();const [reason,setReason]=useState('');const [file,setFile]=useState<File|null>(null);const [evidenceType,setEvidenceType]=useState<typeof EvidenceInputEvidenceType[keyof typeof EvidenceInputEvidenceType]>(EvidenceInputEvidenceType.fdr_receipt);
  const refresh=()=>{qc.invalidateQueries({queryKey:getGetFdrQueryKey(id)});qc.invalidateQueries({queryKey:getListFdrsQueryKey()});qc.invalidateQueries({queryKey:getGetDashboardQueryKey()});qc.invalidateQueries({queryKey:getListActivityQueryKey()})};
  const record=q.data?.record;const allowedActions:Record<string,Array<[string,string]>>={
    draft:[['submit','Submit for review']],submitted:[['start_review','Start review'],['assign','Assign officer']],under_review:[['verify','Verify record'],['request_correction','Request correction'],['reject','Reject record'],['assign','Assign officer'],['add_note','Add review note']],
    correction_required:[['submit','Resubmit for review']],verified:[['request_renewal','Request renewal'],['request_release','Request release'],['close','Close record']],
    renewal_pending:[['start_review','Review renewal'],['verify','Verify renewal']],release_requested:[['mark_released','Mark released'],['close','Close record']],released:[['close','Close record']],
  };
  const runAction=(action:string)=>act.mutate({recordId:id,data:{action:action as typeof FdrActionInputAction[keyof typeof FdrActionInputAction],reason:reason||undefined,note:action==='add_note'?reason||undefined:undefined}}, {onSuccess:refresh});
  const upload=(e:FormEvent)=>{e.preventDefault();if(!file)return;add.mutate({recordId:id,data:{evidenceType,fileName:file.name,contentType:file.type||'application/octet-stream',sizeBytes:file.size||1}},{onSuccess:()=>{setFile(null);refresh()}})};
  if(q.isLoading)return <DashboardSkeleton/>;if(q.isError||!q.data)return <><Link href="/records" className="mb-4 inline-flex items-center gap-2 text-xs font-semibold text-slate-600" data-testid="link-back-records"><ArrowLeft size={15}/>Repository</Link><Panel><StateBox error retry={()=>q.refetch()}/></Panel></>;
  const d=q.data;
  return <div className="page-enter"><Link href="/records" className="mb-4 inline-flex items-center gap-2 text-xs font-semibold text-slate-600 hover:text-[#193958]" data-testid="link-back-records"><ArrowLeft size={15}/>Back to repository</Link>
    <Title eyebrow={`${d.institution.identifier} · Deposit assurance`} title={d.record.referenceNumber} subtitle={`${d.institution.name} · ${d.record.bankName}, ${d.record.branchName}`} action={<Badge tone={statusTone(d.record.status)}>{statusNames[d.record.status]??d.record.status}</Badge>}/>
    {d.record.duplicateOfId&&<div className="mb-4 flex gap-2 rounded-lg border border-amber-200 bg-amber-50 p-3 text-xs text-amber-900" data-testid="warning-duplicate"><AlertTriangle size={16}/>Possible duplicate record linked to {d.record.duplicateOfId}.</div>}
    <div className="grid gap-5 xl:grid-cols-[1.55fr_1fr]"><div className="space-y-5">
      <Panel title="Deposit particulars"><div className="grid grid-cols-2 gap-x-6 gap-y-5 p-5 sm:grid-cols-3">{[['Principal',money(d.record.amount,d.record.currency)],['Issue date',date(d.record.issueDate)],['Maturity date',date(d.record.maturityDate)],['Bank',d.record.bankName],['Branch',d.record.branchName],['Assigned officer',d.record.assignedOfficer??'Unassigned']].map(([k,v])=><div key={k}><div className="text-[9px] font-bold uppercase tracking-[.13em] text-slate-500">{k}</div><div className="mt-1.5 text-sm font-semibold text-[#243d55]" data-testid={`detail-${k.toLowerCase().replaceAll(' ','-')}`}>{v}</div></div>)}
      <div className="col-span-2 sm:col-span-3"><div className="mb-1.5 text-[9px] font-bold uppercase tracking-[.13em] text-slate-500">Assurance risk</div><div className="flex items-center gap-2"><Badge tone={riskTone(d.record.riskLevel)}>{d.record.riskLevel} risk</Badge>{d.record.riskReason&&<span className="text-xs text-slate-600">{d.record.riskReason}</span>}</div></div>{d.record.nextAction&&<div className="col-span-2 rounded-lg bg-[#f6f8fa] p-3 sm:col-span-3"><div className="text-[9px] font-bold uppercase tracking-[.13em] text-slate-500">Next action</div><div className="mt-1 text-xs font-semibold text-[#344e64]">{d.record.nextAction}</div></div>}</div></Panel>
      <Panel title={`Evidence register · ${d.evidence.length}`} right={<Badge tone="slate">Metadata only</Badge>}>{d.evidence.length?<div className="divide-y divide-[#edf0f2]">{d.evidence.map(ev=><div key={ev.id} className="flex items-center gap-3 px-5 py-3.5" data-testid={`evidence-row-${ev.id}`}><div className="grid h-9 w-9 place-items-center rounded-lg bg-[#eef3f6] text-[#38556e]"><FileText size={16}/></div><div className="min-w-0 flex-1"><div className="truncate text-xs font-bold text-slate-700">{ev.fileName}</div><div className="mt-1 text-[10px] text-slate-500">{ev.evidenceType.replaceAll('_',' ')} · {(ev.sizeBytes/1024).toFixed(0)} KB · {date(ev.uploadedAt)}</div></div><Badge tone={ev.status==='sample_evidence'?'blue':'amber'}>{ev.status.replaceAll('_',' ')}</Badge></div>)}</div>:<StateBox empty/>}
        <form onSubmit={upload} className="border-t border-[#edf0f2] p-4"><div className="mb-3 flex flex-wrap gap-2"><select value={evidenceType} onChange={e=>setEvidenceType(e.target.value as typeof EvidenceInputEvidenceType[keyof typeof EvidenceInputEvidenceType])} className="h-9 min-w-0 flex-1 rounded-md border border-slate-200 bg-white px-2 text-[11px]" aria-label="Evidence type" data-testid="select-evidence-type">{Object.entries({fdr_receipt:'FDR receipt',bank_confirmation:'Bank confirmation',authorization_letter:'Authorization letter',other:'Other'}).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select><label className="flex h-9 cursor-pointer items-center gap-2 rounded-md border border-slate-200 px-3 text-[11px] font-semibold text-slate-600 hover:bg-slate-50"><Upload size={14}/>{file?file.name:'Select evidence'}<input type="file" className="sr-only" onChange={e=>setFile(e.target.files?.[0]??null)} data-testid="input-evidence-file"/></label><Button type="submit" disabled={!file||add.isPending} testId="button-add-evidence"><Plus size={14}/>Add</Button></div><p className="text-[10px] leading-relaxed text-amber-800" data-testid="notice-evidence-simulation">Prototype simulation only: only filename and file metadata are recorded. File bytes are not stored or transmitted.</p>{add.isError&&<p className="mt-2 text-xs text-rose-700">Evidence metadata could not be added. Please retry.</p>}</form>
      </Panel>
    </div><div className="space-y-5">
      <Panel title="Review decision"><div className="p-5"><div className="mb-4 rounded-lg bg-[#f7f9fa] p-3 text-[11px] leading-relaxed text-slate-600">Actions are recorded in the prototype audit trail. Add a reason or note to preserve reviewer context.</div><label className="field">Decision note<textarea rows={3} value={reason} onChange={e=>setReason(e.target.value)} placeholder="Record the reason, evidence gap or review note…" className="input resize-y" data-testid="input-action-note"/></label><div className="mt-3 grid gap-2">{(allowedActions[d.record.status]??[]).map(([action,label],i)=><Button key={action} kind={i===0?'primary':'secondary'} disabled={act.isPending} onClick={()=>runAction(action)} testId={`button-action-${action}`}>{act.isPending?'Recording…':label}</Button>)}</div>{act.isError&&<p className="mt-3 text-xs text-rose-700" data-testid="error-action">Action could not be recorded. Confirm your role and try again.</p>}</div></Panel>
      <Panel title="Decision history">{d.history.length?<div className="p-5"><div className="space-y-0">{d.history.map((event,i)=><div key={event.id} className="relative flex gap-3 pb-5 last:pb-0" data-testid={`history-event-${event.id}`}><div className="relative flex w-4 justify-center"><span className="z-10 mt-1 h-2.5 w-2.5 rounded-full border-2 border-[#315a79] bg-white"/>{i<d.history.length-1&&<span className="absolute top-3 bottom-0 w-px bg-slate-200"/>}</div><div className="flex-1"><div className="text-xs font-bold text-slate-700">{event.action.replaceAll('_',' ')}</div><div className="mt-1 text-[10px] text-slate-500">{event.actor} · {niceRole(event.role)}</div><div className="mt-1 text-[10px] text-slate-600">{event.details}</div><div className="mono mt-1.5 text-[9px] text-slate-400">{new Date(event.createdAt).toLocaleString('en-IN')}</div></div></div>)}</div></div>:<StateBox empty/>}</Panel>
      <Panel title="Institution record"><div className="p-5"><div className="flex items-start gap-3"><div className="grid h-10 w-10 shrink-0 place-items-center rounded-lg bg-[#eaf0f4] text-[#35516d]"><Building2 size={18}/></div><div><div className="text-sm font-bold text-[#253d54]">{d.institution.name}</div><div className="mono mt-1 text-[10px] text-slate-500">{d.institution.identifier}</div><div className="mt-1 text-[11px] text-slate-600">{d.institution.state} · {d.institution.region}</div></div></div><Link href={`/institutions/${d.institution.id}`} className="mt-4 inline-flex items-center gap-2 text-[11px] font-bold text-[#315b7d]" data-testid="link-record-institution">View institution profile <ArrowRight size={13}/></Link></div></Panel>
    </div></div>
  </div>;
}

function InstitutionsPage(){
  const [search,setSearch]=useState('');const [page,setPage]=useState(1);const [show,setShow]=useState(false);const q=useListInstitutions({q:search||undefined,page,pageSize:10});const create=useCreateInstitution();const qc=useQueryClient();
  const submit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const d=new FormData(e.currentTarget);create.mutate({data:{identifier:String(d.get('identifier')),name:String(d.get('name')),state:String(d.get('state')),region:String(d.get('region')),contactName:String(d.get('contactName')),contactEmail:String(d.get('contactEmail')),phone:String(d.get('phone'))}},{onSuccess:()=>{setShow(false);qc.invalidateQueries({queryKey:getListInstitutionsQueryKey()})}})};
  const max=Math.max(1,Math.ceil((q.data?.total??0)/(q.data?.pageSize??10)));
  return <div className="page-enter"><Title eyebrow="Institution directory" title="Participating institutions" subtitle="Institution profiles, deposit coverage and outstanding assurance issues." action={<Button onClick={()=>setShow(true)} testId="button-register-institution"><Plus size={15}/>Register institution</Button>}/>
    <Panel className="overflow-hidden"><div className="border-b border-[#edf0f2] p-4"><label className="relative block max-w-[440px]"><Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/><input value={search} onChange={e=>{setSearch(e.target.value);setPage(1)}} placeholder="Search name, identifier or state" className="h-10 w-full rounded-lg border border-[#dce3e9] bg-[#fbfcfd] pl-9 pr-3 text-xs outline-none focus:border-[#547590]" data-testid="input-search-institutions"/></label></div>
      {q.isLoading?<div className="grid gap-3 p-4 md:grid-cols-2 xl:grid-cols-3">{[1,2,3].map(x=><div key={x} className="h-36 animate-pulse rounded-xl bg-slate-100"/> )}</div>:q.isError?<StateBox error retry={()=>q.refetch()}/>:!q.data?.items?.length?<StateBox empty/>:<div className="grid gap-3 p-4 md:grid-cols-2 xl:grid-cols-3">{q.data.items.map(i=><Link key={i.id} href={`/institutions/${i.id}`} className="group rounded-xl border border-[#e2e8ec] p-4 transition hover:border-[#9fb1be] hover:shadow-sm" data-testid={`card-institution-${i.id}`}><div className="flex items-start gap-3"><div className="grid h-10 w-10 shrink-0 place-items-center rounded-lg bg-[#edf2f6] text-[#34536f]"><Building2 size={18}/></div><div className="min-w-0 flex-1"><div className="line-clamp-2 text-[13px] font-bold leading-snug text-[#243d54]">{i.name}</div><div className="mono mt-1 text-[10px] text-slate-500">{i.identifier}</div></div><ArrowRight size={15} className="mt-1 text-slate-300 group-hover:text-[#315b7d]"/></div><div className="mt-4 flex items-center justify-between border-t border-[#edf0f2] pt-3"><span className="text-[10px] text-slate-500">{i.state} · {i.region}</span><span className="text-[10px] font-semibold text-slate-600">{i.fdrCount} FDRs</span></div><div className="mt-2 flex items-center gap-1.5 text-[10px]">{i.openIssues>0?<><span className="h-1.5 w-1.5 rounded-full bg-amber-500"/><span className="text-amber-800">{i.openIssues} open issues</span></>:<><span className="h-1.5 w-1.5 rounded-full bg-emerald-500"/><span className="text-emerald-800">No open issues</span></>}</div></Link>)}</div>}
      <div className="flex items-center justify-between border-t border-[#edf0f2] px-4 py-3"><span className="text-[10px] text-slate-500">{q.data?.total??0} institutions · Page {page} of {max}</span><div className="flex gap-2"><Button kind="secondary" disabled={page<=1} onClick={()=>setPage(p=>p-1)} testId="button-inst-prev"><ChevronLeft size={14}/>Previous</Button><Button kind="secondary" disabled={page>=max} onClick={()=>setPage(p=>p+1)} testId="button-inst-next">Next<ChevronRight size={14}/></Button></div></div>
    </Panel>
    {show&&<Modal title="Register an institution" close={()=>setShow(false)}><form onSubmit={submit} className="space-y-3"><div className="grid gap-3 sm:grid-cols-2">{[['identifier','Institution identifier'],['name','Institution name'],['state','State / UT'],['region','Administrative region'],['contactName','Authorized contact'],['contactEmail','Contact email'],['phone','Contact phone']].map(([key,label])=><label key={key} className={`field ${key==='name'?'sm:col-span-2':''}`}>{label}<input required name={key} type={key==='contactEmail'?'email':'text'} className="input" data-testid={`input-institution-${key}`}/></label>)}</div>{create.isError&&<p className="text-xs text-rose-700">Institution registration failed. Please check the details.</p>}<div className="flex justify-end gap-2 pt-2"><Button kind="secondary" onClick={()=>setShow(false)} testId="button-cancel-institution">Cancel</Button><Button type="submit" disabled={create.isPending} testId="button-submit-institution">{create.isPending?'Registering…':'Register institution'}</Button></div></form></Modal>}
  </div>;
}

function InstitutionPage(){
  const {id=''}=useParams<{id:string}>();const q=useGetInstitution(id,{query:{enabled:!!id,queryKey:getGetInstitutionQueryKey(id)}});const update=useUpdateInstitution();const qc=useQueryClient();const [editing,setEditing]=useState(false);
  const inst=q.data?.institution;
  const save=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();if(!inst)return;const d=new FormData(e.currentTarget);update.mutate({institutionId:id,data:{name:String(d.get('name')),state:String(d.get('state')),region:String(d.get('region')),contactName:String(d.get('contactName')),contactEmail:String(d.get('contactEmail')),phone:String(d.get('phone'))}},{onSuccess:()=>{setEditing(false);qc.invalidateQueries({queryKey:getGetInstitutionQueryKey(id)});qc.invalidateQueries({queryKey:getListInstitutionsQueryKey()})}})};
  if(q.isLoading)return <DashboardSkeleton/>;if(q.isError||!q.data)return <Panel><StateBox error retry={()=>q.refetch()}/></Panel>;
  return <div className="page-enter"><Link href="/institutions" className="mb-4 inline-flex items-center gap-2 text-xs font-semibold text-slate-600" data-testid="link-back-institutions"><ArrowLeft size={15}/>Institution directory</Link>
    <Title eyebrow={`${inst?.identifier} · Institution profile`} title={inst?.name??'Institution'} subtitle={`${inst?.state} · ${inst?.region}`} action={<Button kind="secondary" onClick={()=>setEditing(!editing)} testId="button-edit-institution">{editing?'Cancel':'Edit profile'}</Button>}/>
    <div className="mb-5 grid grid-cols-2 gap-3 md:grid-cols-4">{[['Active FDRs',inst?.fdrCount??0],['Open issues',inst?.openIssues??0],['State / UT',inst?.state??'—'],['Region',inst?.region??'—']].map(([label,val])=><div key={String(label)} className="rounded-xl border border-[#dfe5e9] bg-white p-4"><div className="text-[10px] font-bold uppercase tracking-wider text-slate-500">{label}</div><div className="mt-2 text-lg font-bold text-[#213c56]" data-testid={`institution-stat-${String(label).toLowerCase().replaceAll(' ','-')}`}>{val}</div></div>)}</div>
    {editing&&<Panel className="mb-5" title="Update institution details"><form onSubmit={save} className="grid gap-3 p-5 sm:grid-cols-2">{[['name','Institution name',inst?.name],['state','State / UT',inst?.state],['region','Region',inst?.region],['contactName','Authorized contact',inst?.contactName],['contactEmail','Contact email',inst?.contactEmail],['phone','Contact phone',inst?.phone]].map(([k,l,v])=><label key={String(k)} className="field">{l}<input name={String(k)} defaultValue={String(v??'')} required={k!=='contactEmail'} className="input" data-testid={`input-profile-${k}`}/></label>)}<div className="flex justify-end gap-2 sm:col-span-2">{update.isError&&<span className="mr-auto self-center text-xs text-rose-700">Update failed.</span>}<Button type="submit" disabled={update.isPending} testId="button-save-institution">{update.isPending?'Saving…':'Save changes'}</Button></div></form></Panel>}
    <div className="grid gap-5 xl:grid-cols-[1fr_1.4fr]"><Panel title="Authorized contact"><div className="space-y-4 p-5">{[['Contact person',inst?.contactName],['Email',inst?.contactEmail],['Telephone',inst?.phone],['Registered',date(inst?.createdAt)]].map(([k,v])=><div key={String(k)}><div className="text-[9px] font-bold uppercase tracking-wider text-slate-500">{k}</div><div className="mt-1 text-xs font-semibold text-slate-700" data-testid={`institution-contact-${String(k).toLowerCase().replaceAll(' ','-')}`}>{v||'—'}</div></div>)}</div></Panel>
    <Panel title="Linked FDR records" right={<span className="text-[10px] text-slate-500">{q.data.records.length} records</span>}>{q.data.records.length?<div className="scrollbar-thin overflow-x-auto"><table className="w-full min-w-[570px] text-left"><thead className="bg-[#f8fafb] text-[9px] uppercase tracking-wider text-slate-500"><tr><th className="px-4 py-3">Reference</th><th className="px-4 py-3">Bank</th><th className="px-4 py-3">Principal</th><th className="px-4 py-3">Maturity</th><th className="px-4 py-3">Status</th></tr></thead><tbody className="divide-y divide-slate-100">{q.data.records.map(r=><tr key={r.id} data-testid={`institution-fdr-${r.id}`}><td className="px-4 py-3"><Link href={`/records/${r.id}`} className="mono text-[10px] font-semibold text-[#315b7d]" data-testid={`link-institution-fdr-${r.id}`}>{r.referenceNumber}</Link></td><td className="px-4 py-3 text-xs">{r.bankName}</td><td className="px-4 py-3 mono text-xs">{money(r.amount,r.currency)}</td><td className="px-4 py-3 text-xs">{date(r.maturityDate)}</td><td className="px-4 py-3"><Badge tone={statusTone(r.status)}>{statusNames[r.status]??r.status}</Badge></td></tr>)}</tbody></table></div>:<StateBox empty/>}</Panel></div>
    <div className="mt-5"><Panel title="Outstanding issues">{q.data.outstandingIssues.length?<ul className="space-y-2 p-5">{q.data.outstandingIssues.map((issue,i)=><li key={i} className="flex gap-2 text-xs text-slate-700" data-testid={`issue-${i}`}><AlertTriangle size={15} className="shrink-0 text-amber-600"/>{issue}</li>)}</ul>:<div className="flex items-center gap-2 p-5 text-xs text-emerald-800"><CheckCircle2 size={16}/>No outstanding issues recorded.</div>}</Panel></div>
  </div>;
}

function ActivityPage(){const q=useListActivity({limit:100});const [search,setSearch]=useState('');const [role,setRole]=useState('');const events=useMemo(()=> (q.data??[]).filter(e=>(!search||`${e.actor} ${e.action} ${e.details} ${e.institutionName??''}`.toLowerCase().includes(search.toLowerCase()))&&(!role||e.role===role)),[q.data,search,role]);
 return <div className="page-enter"><Title eyebrow="Accountability register" title="Audit activity" subtitle="A chronological view of actions across the institutional assurance workflow." action={<Button kind="secondary" onClick={()=>window.print()} testId="button-print-audit"><FileText size={14}/>Print view</Button>}/>
 <div className="mb-5 grid grid-cols-2 gap-3 md:grid-cols-3"><div className="rounded-xl border border-[#dfe5e9] bg-white p-4"><div className="text-[10px] font-bold uppercase tracking-wider text-slate-500">Events retrieved</div><div className="display mt-2 text-2xl font-extrabold text-[#183653]" data-testid="activity-total">{q.data?.length??'—'}</div></div><div className="rounded-xl border border-[#dfe5e9] bg-white p-4"><div className="text-[10px] font-bold uppercase tracking-wider text-slate-500">Visible in report</div><div className="display mt-2 text-2xl font-extrabold text-[#183653]" data-testid="activity-visible">{events.length}</div></div><div className="col-span-2 rounded-xl border border-[#dfe5e9] bg-[#f8fafb] p-4 md:col-span-1"><div className="text-[10px] font-bold uppercase tracking-wider text-slate-500">Report note</div><div className="mt-2 text-[11px] leading-relaxed text-slate-600">Filtered report view reflects activity currently available to this demo role.</div></div></div>
 <Panel className="overflow-hidden"><div className="flex flex-col gap-3 border-b border-slate-100 p-4 md:flex-row"><label className="relative flex-1"><Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Find actor, action or institution" className="h-10 w-full rounded-lg border border-slate-200 pl-9 pr-3 text-xs outline-none" data-testid="input-search-activity"/></label><select value={role} onChange={e=>setRole(e.target.value)} className="h-10 rounded-lg border border-slate-200 bg-white px-3 text-xs" aria-label="Filter by role" data-testid="select-filter-role"><option value="">All roles</option>{roles.map(([r,l])=><option value={r} key={r}>{l}</option>)}</select><Button kind="secondary" onClick={()=>{setSearch('');setRole('')}} testId="button-clear-activity">Clear filters</Button></div>{q.isLoading?<div className="p-5"><div className="h-56 animate-pulse rounded bg-slate-100"/></div>:q.isError?<StateBox error retry={()=>q.refetch()}/>:events.length?<div className="divide-y divide-slate-100">{events.map(event=><div key={event.id} className="flex gap-3 px-5 py-4" data-testid={`activity-event-${event.id}`}><div className="grid h-9 w-9 shrink-0 place-items-center rounded-full bg-[#edf2f6] text-[#35536e]"><Activity size={16}/></div><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><span className="text-xs font-bold text-[#243d54]">{event.actor}</span><Badge>{niceRole(event.role)}</Badge><span className="text-xs text-slate-600">{event.action.replaceAll('_',' ')}</span></div><p className="mt-1 text-[11px] leading-relaxed text-slate-600">{event.details}</p><div className="mt-1.5 flex flex-wrap gap-x-3 text-[10px] text-slate-500">{event.institutionName&&<span>{event.institutionName}</span>}{event.recordId&&<Link href={`/records/${event.recordId}`} className="mono text-[#315b7d]" data-testid={`link-event-record-${event.id}`}>Record {event.recordId}</Link>}</div></div><div className="mono shrink-0 text-[9px] text-slate-400">{new Date(event.createdAt).toLocaleString('en-IN',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}</div></div>)}</div>:<StateBox empty/>}</Panel></div>}

function ActivityPanel({events,compact=false}:{events:Array<{id:string;actor:string;role:typeof DemoRole[keyof typeof DemoRole];action:string;details:string;recordId:string|null;institutionName:string|null;createdAt:string}>;compact?:boolean}){return <Panel title="Recent audit activity" right={<Link href="/activity" className="text-[10px] font-bold text-[#315b7d]" data-testid="link-all-activity">Full audit view <ArrowRight className="ml-1 inline" size={12}/></Link>}>{events.length?<div className="divide-y divide-[#edf0f2]">{events.slice(0,compact?4:10).map(ev=><div key={ev.id} className="flex items-start gap-3 px-5 py-3" data-testid={`recent-activity-${ev.id}`}><span className="mt-1.5 h-2 w-2 shrink-0 rounded-full bg-[#c69535]"/><div className="min-w-0 flex-1"><div className="text-xs font-semibold text-slate-700">{ev.actor} <span className="font-normal text-slate-500">{ev.action.replaceAll('_',' ')}</span></div><div className="mt-1 truncate text-[10px] text-slate-500">{ev.details}</div></div><span className="mono shrink-0 text-[9px] text-slate-400">{date(ev.createdAt)}</span></div>)}</div>:<StateBox empty/>}</Panel>}

function AdminPage(){const session=useGetSession();const users=useListDemoUsers();const settings=useGetSettings();const updateUser=useUpdateDemoUser();const updateSettings=useUpdateSettings();const switchRole=useSwitchDemoRole();const qc=useQueryClient();
 const toggle=(id:string,active:boolean)=>updateUser.mutate({userId:id,data:{active}},{onSuccess:()=>qc.invalidateQueries({queryKey:getListDemoUsersQueryKey()})});
 const roleChange=(userId:string,role:typeof DemoRole[keyof typeof DemoRole])=>updateUser.mutate({userId,data:{role}},{onSuccess:()=>qc.invalidateQueries({queryKey:getListDemoUsersQueryKey()})});
 const update=(data:Partial<AppSettings>)=>updateSettings.mutate({data},{onSuccess:()=>qc.invalidateQueries({queryKey:getGetSettingsQueryKey()})});
 const resetDemo=()=>switchRole.mutate({data:{role:DemoRole.administrator}},{onSuccess:()=>qc.invalidateQueries()});
 if(session.data?.role!==DemoRole.administrator)return <><Title eyebrow="Restricted workspace controls" title="Administrator access required" subtitle="Demo-user and workflow configuration is available only in the administrator role."/><Panel><div className="flex items-center gap-3 p-6 text-xs text-slate-600"><ShieldCheck size={20} className="text-amber-700"/>Switch to the administrator demo role using the role selector to continue.</div></Panel></>;
 return <div className="page-enter"><Title eyebrow="Workspace controls" title="Administration" subtitle="Configure the demonstration workflow and manage role-based demo access."/>
 <div className="mb-5 flex gap-3 rounded-xl border border-[#ead6aa] bg-[#fff8e9] p-4"><AlertTriangle className="mt-0.5 shrink-0 text-[#9b7123]" size={17}/><div><div className="text-xs font-bold text-[#5c491f]">Demo controls only</div><p className="mt-1 text-[11px] leading-relaxed text-[#71613b]">Changes affect this prototype workspace. They do not grant real access or alter any official institutional assurance process.</p></div></div>
 <div className="grid gap-5 xl:grid-cols-[1.35fr_1fr]"><Panel title="Demo access roster" right={<Badge tone="amber">Prototype users</Badge>}>{users.isLoading?<div className="p-5"><div className="h-44 animate-pulse rounded bg-slate-100"/></div>:users.isError?<StateBox error retry={()=>users.refetch()}/>:users.data?.length?<div className="divide-y divide-slate-100">{users.data.map(user=><div key={user.id} className="flex flex-col gap-3 px-4 py-4 sm:flex-row sm:items-center" data-testid={`demo-user-${user.id}`}><div className="grid h-9 w-9 shrink-0 place-items-center rounded-full bg-[#e9eff3] text-[10px] font-bold text-[#38556e]">{initials(user.fullName)}</div><div className="min-w-0 flex-1"><div className="truncate text-xs font-bold text-slate-700">{user.fullName}</div><div className="truncate text-[10px] text-slate-500">{user.email}</div></div><select value={user.role} onChange={e=>roleChange(user.id,e.target.value as typeof DemoRole[keyof typeof DemoRole])} aria-label={`Change role for ${user.fullName}`} className="h-9 rounded-md border border-slate-200 bg-white px-2 text-[10px]" data-testid={`select-user-role-${user.id}`}>{roles.map(([role,label])=><option value={role} key={role}>{label}</option>)}</select><button onClick={()=>toggle(user.id,!user.active)} disabled={updateUser.isPending} className={`rounded-md px-3 py-2 text-[10px] font-bold ${user.active?'bg-emerald-50 text-emerald-800':'bg-slate-100 text-slate-600'}`} data-testid={`button-user-active-${user.id}`}>{user.active?'Active':'Inactive'} · {user.active?'Deactivate':'Activate'}</button></div>)}</div>:<StateBox empty/>}{updateUser.isError&&<div className="border-t border-slate-100 px-4 py-3 text-xs text-rose-700">Could not update demo user. Try again.</div>}</Panel>
 <div className="space-y-5"><Panel title="Workflow thresholds"><div className="space-y-5 p-5">{settings.isLoading?<div className="h-36 animate-pulse rounded bg-slate-100"/>:settings.isError?<StateBox error retry={()=>settings.refetch()}/>:settings.data&&<><label className="field">Maturity warning window <span className="mt-1 block text-[10px] font-normal text-slate-500">Flag deposits this many days before maturity.</span><div className="mt-2 flex items-center gap-3"><input type="number" min="1" max="365" defaultValue={settings.data.maturityWarningDays} onBlur={e=>{const n=Number(e.target.value);if(n>0&&n<=365&&n!==settings.data?.maturityWarningDays)update({maturityWarningDays:n})}} className="input max-w-[120px]" data-testid="input-maturity-warning"/><span className="text-xs text-slate-500">days</span></div></label><label className="flex items-start justify-between gap-4 border-t border-slate-100 pt-4"><span><span className="block text-xs font-bold text-slate-700">Require bank confirmation</span><span className="mt-1 block text-[10px] text-slate-500">Include confirmation in reviewer checklist.</span></span><input type="checkbox" checked={settings.data.requireBankConfirmation} onChange={e=>update({requireBankConfirmation:e.target.checked})} className="mt-1 h-4 w-4 accent-[#183653]" data-testid="toggle-bank-confirmation"/></label><label className="flex items-start justify-between gap-4 border-t border-slate-100 pt-4"><span><span className="block text-xs font-bold text-slate-700">Maturity notifications</span><span className="mt-1 block text-[10px] text-slate-500">Show alerts in the workspace for approaching dates.</span></span><input type="checkbox" checked={settings.data.notifyOnMaturity} onChange={e=>update({notifyOnMaturity:e.target.checked})} className="mt-1 h-4 w-4 accent-[#183653]" data-testid="toggle-maturity-notifications"/></label></>}</div>{updateSettings.isError&&<div className="border-t border-slate-100 px-5 py-3 text-xs text-rose-700">Settings update failed.</div>}{updateSettings.isSuccess&&<div className="border-t border-slate-100 px-5 py-2 text-[10px] text-emerald-700">Workflow setting saved.</div>}</Panel>
 <Panel title="Role preview"><div className="p-5"><p className="text-[11px] leading-relaxed text-slate-600">Explore the interface from an authorized demo role. Role switching does not represent real identity verification or access approval.</p><div className="mt-4 grid grid-cols-2 gap-2">{roles.map(([role,label])=><Button key={role} kind="secondary" onClick={()=>switchRole.mutate({data:{role}},{onSuccess:()=>qc.invalidateQueries()})} testId={`button-preview-${role}`}>{label}</Button>)}</div>{switchRole.isError&&<p className="mt-3 text-xs text-rose-700">Role preview unavailable.</p>}</div></Panel></div></div>
 <Panel className="mt-5" title="Prototype environment"><div className="flex flex-col gap-4 p-5 sm:flex-row sm:items-center sm:justify-between"><div><div className="text-xs font-bold text-slate-700">Return to administrator view</div><p className="mt-1 text-[11px] text-slate-500">Reset the current preview role to administrator for this demonstration.</p></div><Button kind="secondary" disabled={switchRole.isPending} onClick={resetDemo} testId="button-reset-role"><LogOut size={14}/>Reset role</Button></div></Panel>
 </div>;
}

export default App;
